"""Offline comparison of two observed CareerOneStop UI runs; no network or credentials."""
import json,pathlib,hashlib,importlib.util,urllib.parse
D=pathlib.Path(__file__).parent
spec=importlib.util.spec_from_file_location('reference',D.parent/'validation-053-external/compare.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
source=json.loads((D.parent/'validation-053-external/frozen-inputs.json').read_text());byid={r['id']:r for r in source['rows']};observedChartScores={'life-005':[11,10,16,11,7,10],'new049-001':[10,10,6,11,16,6]};out=[]
for id,observed in observedChartScores.items():
    packet=json.loads((D/(id+'-results.json')).read_text());items=packet['crosswalk'];row=byid[id]
    assert len(items)==30 and len({q['localIndex'] for q in items})==30
    for q in items:
        official=source['instrument']['items'][q['localIndex']-1];assert official['text']==q['text'] and official['theme']==q['theme'];assert q['answer']==row['answers'][q['localIndex']-1]
    encoded=''.join(str(q['answer']) for q in items);assert urllib.parse.parse_qs(urllib.parse.urlparse(packet['url']).query)['answers']==[encoded]
    scores=[sum(q['answer']-1 for q in items if q['theme']==t) for t in 'RIASEC'];assert scores==observed
    local30={c['soc']:m.pearson(scores,c['vector']) for c in source['careers'] if c['vector']};local60={c['soc']:r for c,r in zip(source['careers'],row['correlations']) if r is not None}
    returned=[]
    for x in packet['results']:
        link=next(x for x in x['links'] if 'occupation-profile' in x['href']);soc=urllib.parse.parse_qs(urllib.parse.urlparse(link['href']).query)['onetcode'][0];returned.append({'soc':soc,'title':link['title'],'fit':x['cells'][0]})
    assert len({r['soc'] for r in returned})==len(returned)
    shared=[r for r in returned if r['soc'] in local30];bad=[dict(r,localCorrelation=local30[r['soc']],localTier=m.tier(local30[r['soc']])) for r in shared if {'Best':3,'Great':2,'Good':1}[r['fit']]!=m.tier(local30[r['soc']])]
    remoteStrong={r['soc'] for r in returned if r['fit'] in ['Best','Great'] and r['soc'] in local30};localStrong30={soc for soc,r in local30.items() if r>=.608};localStrong60={soc for soc,r in local60.items() if r>=.608};ids=sorted(local30);v30=[local30[s] for s in ids];v60=[local60[s] for s in ids]
    out.append({'id':id,'phase':row['phase'],'sharedExactItems':30,'localInstrumentDenominator':60,'externalInstrumentDenominator':30,'chartScoreSource':'Visible six bar labels, transcribed from saved chart PNG; all six independently recomputed from the copied item responses','localFull60Scores':row['raw'],'observed30Scores':observed,'recomputed30Scores':scores,'scoresAgree':True,'sourceRows':len(returned),'sharedReturnedSOC':len(shared),'sharedReturnedFitLabelsAgree':len(shared)-len(bad),'fitDisagreements':bad,'strongSetJaccardWithSame30Answers':m.jaccard(remoteStrong,localStrong30),'remoteStrongOutsideCatalog':[r for r in returned if r['fit'] in ['Best','Great'] and r['soc'] not in local30],'localStrong30NotReturned':sorted(localStrong30-remoteStrong),'strongSetJaccardVersusFull60':m.jaccard(remoteStrong,localStrong60),'formulaOnlyFull60VersusSubset30':{'occupationDenominator':len(ids),'spearman':m.spearman(v30,v60),'kendallTauB':m.kendall(v30,v60),'topKJaccard':{str(k):m.jaccard(m.topk(v30,ids,k),m.topk(v60,ids,k)) for k in [5,10,20,50]}},'liveServiceRankMetrics':None,'rankLimit':'CareerOneStop displays fit bands then alphabetical titles. Rank metrics compare local numeric 60-vs-30 formulas only, not that display order.','careerResults':returned})
report={'service':'CareerOneStop Interest Assessment','execution':'Two real public browser UI runs, no account, no signup, no private data; exact shared item responses copied from pre-existing public synthetic profiles','captureDate':'2026-10-19 America/Chicago','measurementFamily':'O*NET; not independent psychometric evidence','selectedProfiles':['life-005','new049-001'],'selectionReason':'Contrasting artistic and enterprising frozen profiles, chosen before CareerOneStop outputs. Convenience panel of development cases, zero holdouts tuned.','sourceURL':'https://www.careeronestop.org/Toolkit/Careers/interest-assessment-help.aspx','originalOfficialSummaryUnchanged':True,'profiles':out}
(D/'results.json').write_text(json.dumps(report,indent=2)+'\n');summary={k:v for k,v in report.items() if k!='profiles'};summary['profiles']=[{k:v for k,v in r.items() if k!='careerResults'} for r in out];(D/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
